arguments.command:
cd /tmp && mkdir -p binlog-parser && cat > binlog-parser/Program.cs << 'CSHARP'
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

Console.WriteLine("=== BUILD RESULT: " + (build.Succeeded ? "SUCCESS" : "FAILED") + " ===\n");

// Find all errors
var errors = new List<(string File, int Line, int Col, string Code, string Message, string Project)>();
build.VisitAllChildren<Error>(error => {
    errors.Add((error.File ?? "", error.LineNumber, error.ColumnNumber, error.Code ?? "", error.Text ?? error.ToString(), error.ProjectFile ?? ""));
});

Console.WriteLine($"Total errors: {errors.Count}\n");
foreach (var e in errors)
{
    Console.WriteLine($"Project: {e.Project}");
    Console.WriteLine($"  File: {e.File}:{e.Line},{e.Col}");
    Console.WriteLine($"  Code: {e.Code}");
    Console.WriteLine($"  Message: {e.Message}");
    Console.WriteLine();
}

// Show project dependency info
Console.WriteLine("=== PROJECT REFERENCES ===");
build.VisitAllChildren<Project>(project => {
    Console.WriteLine($"Project: {project.Name} (Succeeded={project.Succeeded})");
});
CSHARP
