using System;
using System.Collections.Generic;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Try to find source file contents in the binlog
var sourceFiles = new HashSet<string>();
build.VisitAllChildren<SourceFile>(sf => {
    Console.WriteLine($"SourceFile: {sf.Name} => {sf.SourceFilePath}");
});

// Look for CscCommandLineArgs or similar
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc")
    {
        Console.WriteLine($"\n=== Csc Task in {task.Parent} ===");
        foreach (var child in task.Children)
        {
            if (child is Folder f && f.Name == "CommandLineArguments")
            {
                foreach (var item in f.Children)
                    Console.WriteLine($"  {item}");
            }
        }
    }
});

// Also look at the actual error file content via SourceFilesWithContent
Console.WriteLine("\n=== Looking for embedded source ===");
build.VisitAllChildren<SourceFileLine>(line => {
    Console.WriteLine($"Line: {line}");
});
