cd /tmp/binlog-parser && cat > Program.cs << 'CSHARP'
using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get all unique string-like nodes
build.VisitAllChildren<CscCommandLineArgs>(node => {
    Console.WriteLine($"CscArgs: {node}");
});

// Try to look for the Csc task's command line
build.VisitAllChildren<Task>(task => {
    if (task.Name == "Csc")
    {
        Console.WriteLine($"\n=== Csc in {task.Parent} ===");
        task.VisitAllChildren<Property>(p => {
            Console.WriteLine($"  Prop: {p.Name} = {p.Value}");
        });
        task.VisitAllChildren<Item>(item => {
            Console.WriteLine($"  Item: {item.Name} = {item.Text}");
        });
        // Also check Message children
        task.VisitAllChildren<Message>(m => {
            if (m.Text != null && m.Text.Contains("/")) 
                Console.WriteLine($"  Msg: {m.Text?.Substring(0, Math.Min(500, m.Text.Length))}");
        });
    }
});
