using System;
using Microsoft.Build.Logging.StructuredLogger;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Check if Api had build failures (cascading from Services)
Console.WriteLine("=== Api project status ===");
build.VisitAllChildren<Project>(project => {
    if (project.Name == "Api.csproj")
    {
        var hasErrors = false;
        project.VisitAllChildren<Error>(e => { hasErrors = true; });

        // Check for "project dependency failed" type messages
        project.VisitAllChildren<Message>(m => {
            if (m.Text != null && (m.Text.Contains("fail") || m.Text.Contains("error") || m.Text.Contains("skip")))
                Console.WriteLine($"  MSG: {m.Text.Substring(0, Math.Min(200, m.Text.Length))}");
        });

        // Check for build not attempted
        Console.WriteLine($"  HasErrors: {hasErrors}");
    }
});

// Check the overall build result
Console.WriteLine($"\nBuild succeeded: {build.Succeeded}");

// Look at the dependency graph
Console.WriteLine("\n=== Build order / dependencies ===");
build.VisitAllChildren<Target>(target => {
    if (target.Name == "ResolveProjectReferences" && target.Project != null)
    {
        Console.WriteLine($"  ResolveProjectReferences in {target.Project.Name}");
        target.VisitAllChildren<Message>(m => {
            if (m.Text != null && m.Text.Length < 300)
                Console.WriteLine($"    {m.Text}");
        });
    }
});
